import base64
import json
import os
from typing import Any, Dict, List, Optional

import boto3


def _as_text(value: Any) -> Optional[str]:
    if value is None:
        return None
    if isinstance(value, str):
        return value.strip() or None
    if isinstance(value, dict):
        for key in ("Value", "value", "Text", "text", "Content", "content", "Data", "data"):
            if key in value and value[key] is not None:
                txt = _as_text(value[key])
                if txt:
                    return txt
        if "normalizedValue" in value and value["normalizedValue"] is not None:
            return _as_text(value["normalizedValue"])
    if isinstance(value, list):
        parts = [_as_text(v) for v in value]
        parts = [p for p in parts if p]
        return " ".join(parts) if parts else None
    return str(value).strip() or None


def _field_text(field: Dict[str, Any], *keys: str) -> Optional[str]:
    for key in keys:
        if key in field:
            txt = _as_text(field.get(key))
            if txt:
                return txt
    return None


def _line_item_text(item: Dict[str, Any], *keys: str) -> Optional[str]:
    for key in keys:
        if key in item:
            txt = _as_text(item.get(key))
            if txt:
                return txt
    return None


def _normalize_items(line_items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []
    for item in line_items or []:
        row: Dict[str, Any] = {}

        desc = (
            _line_item_text(item, "Description")
            or _line_item_text(item, "Item")
            or _line_item_text(item, "ProductName")
            or _line_item_text(item, "Name")
        )
        qty = _line_item_text(item, "Quantity", "Qty")
        unit_price = _line_item_text(item, "Price", "UnitPrice", "Unit Price")
        amount = _line_item_text(item, "Amount", "TotalPrice", "LineTotal", "ExtendedPrice")
        tax = _line_item_text(item, "Tax", "TaxAmount")

        if desc is not None:
            row["description"] = desc
        if qty is not None:
            row["quantity"] = qty
        if unit_price is not None:
            row["unit_price"] = unit_price
        if amount is not None:
            row["amount"] = amount
        if tax is not None:
            row["tax"] = tax

        if row:
            items.append(row)
    return items


def _extract_from_expense_documents(expense_documents: List[Dict[str, Any]]) -> Dict[str, Any]:
    merchant = None
    tax = None
    total = None
    items: List[Dict[str, Any]] = []

    for doc in expense_documents or []:
        summary_fields = doc.get("SummaryFields", []) or []
        for field in summary_fields:
            ftype = _field_text(field, "Type", "TypeText", "LabelDetection", "LabelDetectionText")
            value = _field_text(field, "ValueDetection", "ValueText", "Value")
            if not value:
                continue
            ftype_norm = (ftype or "").strip().lower()

            if merchant is None and ftype_norm in {"merchant", "vendor", "supplier", "seller"}:
                merchant = value
            elif tax is None and ftype_norm in {"tax", "tax amount", "vat", "gst"}:
                tax = value
            elif total is None and ftype_norm in {"total", "amount due", "grand total", "net payable"}:
                total = value
            elif merchant is None and ftype_norm in {"name", "company name", "business name"}:
                merchant = value

        line_item_groups = doc.get("LineItemGroups", []) or []
        for group in line_item_groups:
            items.extend(_normalize_items(group.get("LineItems", []) or []))

    return {
        "merchant": merchant,
        "tax": tax,
        "total": total,
        "items": items,
    }


def extract_receipt(image_bytes: bytes) -> Dict[str, Any]:
    """
    Extract merchant, tax, total, and items from a receipt using Amazon Textract AnalyzeExpense.

    Returns a dict with keys:
      - merchant
      - tax
      - total
      - items
    """
    client = boto3.client("textract")
    response = client.analyze_expense(Document={"Bytes": image_bytes})
    expense_documents = response.get("ExpenseDocuments", []) or []
    result = _extract_from_expense_documents(expense_documents)

    # Include raw response for callers that need additional fields while keeping the core output concise.
    result["raw_response"] = response
    return result


def extract_receipt_from_file(path: str) -> Dict[str, Any]:
    with open(path, "rb") as f:
        return extract_receipt(f.read())


def extract_receipt_from_base64(data: str) -> Dict[str, Any]:
    return extract_receipt(base64.b64decode(data))


if __name__ == "__main__":
    import sys

    if len(sys.argv) < 2:
        raise SystemExit("Usage: python script.py <receipt_image_path>")
    output = extract_receipt_from_file(sys.argv[1])
    print(json.dumps(output, indent=2, ensure_ascii=False))
